package com.studentgig.controller; import com.studentgig.model.User; import com.studentgig.repository.UserRepository; import org.springframework.web.bind.annotation.*; import jakarta.servlet.http.*; import java.util.*;
@RestController @RequestMapping("/api/profile") public class ProfileController {final UserRepository r;ProfileController(UserRepository r){this.r=r;}@PutMapping public Object update(@RequestBody User p,HttpSession s){Object id=s.getAttribute("userId");if(id==null)return Map.of("error","Please login");User u=r.findById((Long)id).orElseThrow();p.id=u.id;p.email=u.email;p.password=u.password;p.role=u.role;p.profileViews=u.profileViews;return scrub(r.save(p));}private User scrub(User u){u.password=null;return u;}}
